-- Run after the existing synthetic finance assertions. No hosted data needed.
reset role;
set request.jwt.claim.role='authenticated';set request.jwt.claim.sub='00000000-0000-4000-8000-000000000010';
set role authenticated;
select learn_quickbooks_customer_link(fixture_id(1),fixture_customer_version(),fixture_id(501),3,'Restore reviewed synthetic link');
reset role;
create temporary table retained_finance_before as select (select count(*) from learn_quickbooks_source_versions) versions,(select count(*) from learn_quickbooks_pages) pages,(select sum(revision) from learn_quickbooks_customer_links) revisions;
update feature_flags set value='false' where tenant_id=fixture_id(1) and flag='learn.inputs.quickbooks.enabled';
set role authenticated;
select fixture_assert(learn_quickbooks_customer_finance(fixture_id(1),fixture_id(501),'production',null,'Read saved accounts')->>'records'='6','capture disabled: authorised operator reads saved finance');
select fixture_assert(jsonb_array_length(learn_quickbooks_customer_candidates(fixture_id(1),'production','Review retained identities')->'rows')>0,'capture disabled: operator can inspect retained identity candidates');
select fixture_finance_denied('select learn_quickbooks_customer_link(fixture_id(1),fixture_customer_version(),null,4,''Must not mutate while input disabled'')','42501');
select fixture_finance_denied('select learn_quickbooks_customer_finance(fixture_id(2),fixture_id(501),''production'',null,''Wrong tenant'')','42501');
set request.jwt.claim.sub='00000000-0000-4000-8000-000000000011';
select fixture_assert(learn_quickbooks_customer_finance(fixture_id(1),fixture_id(501))->>'records'='6','capture disabled: existing tenant admin reads saved finance');
select fixture_finance_denied('select learn_quickbooks_customer_candidates(fixture_id(1),''production'',''Admin is not operator'')','42501');
reset role;update profiles set role='staff' where id=fixture_id(11);set role authenticated;
select fixture_finance_denied('select learn_quickbooks_customer_finance(fixture_id(1),fixture_id(501))','42501');
reset role;update profiles set role='admin' where id=fixture_id(11);update auth.users set banned_until=clock_timestamp()+interval '1 hour' where id=fixture_id(11);set role authenticated;
select fixture_finance_denied('select learn_quickbooks_customer_finance(fixture_id(1),fixture_id(501))','42501');
reset role;update auth.users set banned_until=null where id=fixture_id(11);
update feature_flags set value='false' where tenant_id=fixture_id(1) and flag='learn.enabled';set role authenticated;
select fixture_finance_denied('select learn_quickbooks_customer_finance(fixture_id(1),fixture_id(501))','42501');
set request.jwt.claim.sub='00000000-0000-4000-8000-000000000010';
select fixture_finance_denied('select learn_quickbooks_customer_finance(fixture_id(1),fixture_id(501),''production'',null,''Master remains off'')','42501');
reset role;
select fixture_assert(not has_function_privilege('authenticated','learn_quickbooks_retained_finance_access(uuid,text)','execute') and not has_function_privilege('anon','learn_quickbooks_retained_finance_access(uuid,text)','execute') and not has_function_privilege('service_role','learn_quickbooks_retained_finance_access(uuid,text)','execute'),'internal access helper not exposed');
select fixture_assert((select versions=(select count(*) from learn_quickbooks_source_versions) and pages=(select count(*) from learn_quickbooks_pages) and revisions=(select sum(revision) from learn_quickbooks_customer_links) from retained_finance_before),'reads preserve sources, pages and link revisions');
update feature_flags set value='true' where tenant_id=fixture_id(1);
